import { useEffect } from 'react'
import { Pressable } from 'react-native'
import Animated, {
	interpolate,
	interpolateColor,
	useAnimatedStyle,
	useSharedValue,
	withTiming
} from 'react-native-reanimated'
import * as Feedback from 'expo-haptics'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'

interface SwitchProps {
	value: boolean
	onChange: (value: boolean) => void
	duration?: number
	trackColors?: { on: string; off: string }
	haptics?: boolean
}

export const Switch = ({
	value,
	onChange,
	duration = 200,
	trackColors = { on: '#82cab2', off: '#fa7f7c' },
	haptics = true
}: SwitchProps) => {
	const { theme } = useTheme()
	const height = useSharedValue(0)
	const width = useSharedValue(0)
	const animatedValue = useSharedValue(value ? 1 : 0)

	useEffect(() => {
		animatedValue.set(withTiming(value ? 1 : 0, { duration }))
	}, [value, duration, animatedValue])

	const trackAnimatedStyle = useAnimatedStyle(() => {
		const color = interpolateColor(
			animatedValue.get(),
			[0, 1],
			[trackColors.off, trackColors.on]
		)

		return {
			backgroundColor: color,
			borderRadius: height.get() / 2
		}
	})

	const thumbAnimatedStyle = useAnimatedStyle(() => {
		const moveValue = interpolate(
			animatedValue.get(),
			[0, 1],
			[0, width.get() - height.get()]
		)

		return {
			transform: [{ translateX: moveValue }],
			borderRadius: height.get() / 2
		}
	})

	const handlePress = () => {
		onChange(!value)
		if (haptics) {
			Feedback.impactAsync(Feedback.ImpactFeedbackStyle.Light)
		}
	}

	return (
		<Pressable onPress={handlePress}>
			<Animated.View
				onLayout={(e) => {
					height.set(e.nativeEvent.layout.height)
					width.set(e.nativeEvent.layout.width)
				}}
				style={[switchStyles.track, trackAnimatedStyle]}
			>
				<Animated.View
					style={[switchStyles.thumb(theme), thumbAnimatedStyle]}
				/>
			</Animated.View>
		</Pressable>
	)
}

const switchStyles = defineStyles({
	track: {
		alignItems: 'flex-start',
		width: 36,
		height: 20,
		padding: 3
	},
	thumb: (theme: Theme) => ({
		height: '100%',
		aspectRatio: 1,
		backgroundColor: colors[theme].background
	})
})
